using System;
using System.ComponentModel;
namespace supp { public class BotProfile : INotifyPropertyChanged { private string _status="offline"; public string Id{get;set;} public string Name{get;set;} public string Folder{get;set;} public bool Enabled{get;set;}=true; public bool Autostart{get;set;} public bool UseProxy{get;set;}=true; public string EntryPoint{get;set;}="bot.py"; public string Template{get;set;}="scenario"; public string Status{get=>_status;set{if(_status==value)return;_status=value;PropertyChanged?.Invoke(this,new PropertyChangedEventArgs(nameof(Status)));PropertyChanged?.Invoke(this,new PropertyChangedEventArgs(nameof(StatusIcon)));}} public string StatusIcon{get{ if(string.Equals(Status,"online",StringComparison.OrdinalIgnoreCase))return "🟢"; if(string.Equals(Status,"starting",StringComparison.OrdinalIgnoreCase))return "🟡"; if(string.Equals(Status,"error",StringComparison.OrdinalIgnoreCase))return "🔴"; return "⚪";}} public event PropertyChangedEventHandler PropertyChanged; } }
